from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()
items = []


@app.post("/add/{x}")
def add(x: int):
    items.append(x)
    return len(items)


@app.get("/sum")
def total():
    return sum(items)


client = TestClient(app)
print(client.post("/add/5").json())
print(client.post("/add/7").json())
print(client.get("/sum").json())
print(client.get("/add/1").status_code)
